/** Approved presentation components. Annual engine rows remain the only forecast source. */
const finite=Number.isFinite;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=(v,d=1)=>finite(v)?v.toLocaleString('en-US',{maximumFractionDigits:d}):'—';
const percent=v=>finite(v)?number(v*100)+'%':'Unavailable';
const url=s=>/^https?:\/\//.test(s||'')?s:null;

export function growthChartData(rows,{stableYear,explicitYears=1,mode='annual'}={}){
 stableYear=stableYear??rows.at(-1)?.year;
 if(!Number.isInteger(stableYear)||stableYear<1)return null;
 const explicit=mode==='annual'||mode==='maintain'?Math.max(1,explicitYears):1;
 const years=rows.filter(r=>r.year<=stableYear).map(r=>({year:r.year,value:r.growth,kind:r.year===stableYear?'stable':r.year<=explicit?(mode==='maintain'&&r.year>1?'held':'input'):'fade'}));
 if(years.length!==stableYear||years.some((r,i)=>r.year!==i+1||!finite(r.value)))return null;
 const all=years.map(r=>r.value*100),lo=Math.min(0,...all),hi=Math.max(0,...all);
 // A common rounded scale across sequential rows supports negative and zero rates.
 const magnitude=Math.max(10,hi-lo),step=magnitude<=50?10:magnitude<=100?20:50;
 const min=Math.floor(lo/step)*step,max=Math.max(min+step,Math.ceil(hi/step)*step);
 return {years,min,max,zero:(0-min)/(max-min)*100,stableYear};
}
function element(document,tag,className,text){const e=document.createElement(tag);e.className=className;if(text!==undefined)e.textContent=text;return e;}
const charts=new WeakMap();
export function releaseApprovedChart(host){charts.get(host)?.observer?.disconnect();}
function layoutGrowth(host,state){const width=state.bars.getBoundingClientRect?.().width;if(!(width>0))return;const capacity=Math.max(4,Math.floor((width+5)/35)),columns=Math.ceil(state.count/Math.ceil(state.count/capacity));state.bars.setAttribute('style',`grid-template-columns:repeat(${columns},minmax(0,1fr));`);}
export function updateGrowthChart(host,rows,options={}){
 if(!host)return;
 const data=growthChartData(rows||[],options),document=host.ownerDocument;
 if(!data){host.setAttribute('data-state','unavailable');host.setAttribute('aria-label','Growth path unavailable until the model inputs are valid.');for(const c of host.querySelectorAll('[data-growth-year]'))c.hidden=true;let note=host.querySelector('.approved-chart-message');if(!note){note=element(document,'p','approved-chart-message');host.appendChild(note);}note.hidden=false;note.textContent='Correct the model inputs to see the complete growth path.';return;}
 host.setAttribute('data-state','current');host.setAttribute('data-identity',options.identity||'');host.setAttribute('aria-label',`Every forecast year from year 1 to stable growth in year ${data.stableYear}. Values are annual revenue growth percentages.`);
 let state=charts.get(host);if(!state){host.innerHTML='<div class="approved-plot-heading"><b>Your complete growth path · %</b><span data-growth-endpoint></span></div><p class="approved-scale-note" data-growth-scale></p><div class="approved-growth-bars" role="list" aria-label="Projected annual revenue growth"></div><div class="approved-growth-key"><span class="is-input">Editable assumptions</span><span class="is-fade">Calculated path</span><span class="is-stable">Stable endpoint</span></div><p class="approved-chart-message" hidden></p>';state={bars:host.querySelector('.approved-growth-bars'),columns:new Map()};charts.set(host,state);const Observer=document.defaultView?.ResizeObserver||globalThis.ResizeObserver;if(typeof Observer==='function'){state.observer=new Observer(()=>layoutGrowth(host,state));state.observer.observe(state.bars);}}
 state.count=data.years.length;layoutGrowth(host,state);
 host.querySelector('.approved-chart-message').hidden=true;host.querySelector('[data-growth-endpoint]').textContent=`Year 1 → Year ${data.stableYear}`;host.querySelector('[data-growth-scale]').textContent=`Common scale: ${number(data.min)}% to ${number(data.max)}% · zero baseline shown`;
 const retained=new Set(data.years.map(r=>r.year));for(const [year,col] of state.columns)if(!retained.has(year)){col.remove();state.columns.delete(year);}
 for(const point of data.years){let col=state.columns.get(point.year);if(!col){col=element(document,'div','approved-growth-column');col.setAttribute('data-growth-year',point.year);col.setAttribute('role','listitem');col.innerHTML='<div class="approved-growth-track"><span class="approved-growth-value"></span><span class="approved-growth-bar"></span></div><span class="approved-growth-year"></span>';state.columns.set(point.year,col);state.bars.appendChild(col);}col.hidden=false;col.className=`approved-growth-column is-${point.kind}`;const value=point.value*100,height=Math.abs(value)/(data.max-data.min)*100,bottom=value>=0?data.zero:data.zero-height;col.setAttribute('aria-label',`Year ${point.year}: ${number(value,3)} percent, ${point.kind==='stable'?'stable endpoint':point.kind==='input'?'editable assumption':point.kind==='held'?'held assumption':'calculated path'}`);col.setAttribute('style',`--growth-zero:${data.zero}%;`);col.querySelector('.approved-growth-bar').setAttribute('style',`height:${height}%;bottom:${bottom}%;`);col.querySelector('.approved-growth-value').textContent=number(value,1);col.querySelector('.approved-growth-value').setAttribute('style',`bottom:${value>=0?data.zero+height:data.zero}%;`);col.querySelector('.approved-growth-year').textContent='Y'+point.year;}
}

export function updateProfitChart(host,rows,currency='USD'){
 if(!host)return;const mature=rows?.at(-1),before=mature?.revenue>0?mature.ebit/mature.revenue*100:NaN,after=mature?.revenue>0?mature.nopat/mature.revenue*100:NaN;
 if(!finite(before)||!finite(after)){host.setAttribute('data-state','unavailable');host.innerHTML='<p class="approved-chart-message">Correct the model inputs to see the mature profit illustration.</p>';return;}
 if(host.getAttribute('data-state')!=='current'){host.innerHTML='<div class="approved-plot-heading"><b>For every 100 of revenue</b><span data-profit-currency></span></div><div class="approved-profit-row"><div><span>Operating profit</span><b data-profit-before></b></div><div class="approved-profit-track"><span data-profit-bar="before"></span></div></div><div class="approved-profit-row"><div><span>After cash tax</span><b data-profit-after></b></div><div class="approved-profit-track"><span data-profit-bar="after"></span></div></div><div class="approved-profit-axis"><span data-profit-axis-min>0</span><span data-profit-axis-middle></span><span data-profit-axis-max></span></div><p class="micro">After-tax operating profit is before reinvestment and financing. It is not free cash flow.</p>';host.setAttribute('data-state','current');}
 const min=Math.min(0,Math.floor(Math.min(before,after)/25)*25),max=Math.max(50,Math.ceil(Math.max(before,after)/25)*25),span=max-min,zero=-min/span*100;host.querySelector('[data-profit-currency]').textContent=`${currency} · final forecast year ${mature.year}`;host.querySelector('[data-profit-before]').textContent=number(before,2);host.querySelector('[data-profit-after]').textContent=number(after,2);host.querySelector('[data-profit-axis-min]').textContent=number(min);host.querySelector('[data-profit-axis-middle]').textContent=number((min+max)/2);host.querySelector('[data-profit-axis-max]').textContent=number(max);for(const [name,value]of [['before',before],['after',after]]){const bar=host.querySelector('[data-profit-bar="'+name+'"]'),width=Math.abs(value)/span*100;bar.setAttribute('style',`width:${width}%;left:${value<0?zero-width:zero}%;`);bar.parentNode.setAttribute('style',`--profit-zero:${zero}%;`);}host.setAttribute('aria-label',`In final forecast year ${mature.year}, every 100 ${currency} of revenue produces ${number(before,2)} operating profit and ${number(after,2)} after cash tax, before reinvestment.`);
}

export function evidenceComparison(e,assumption,key){
 const latest=e.series?.at(-1),anchor=key==='targetMargin'&&finite(e.ttm?.value)?e.ttm:latest;
 if(!['growth','targetMargin'].includes(key)||!finite(assumption)||!finite(anchor?.value))return 'Reported observations are context for your judgment; they do not set an assumption.';
 const difference=(assumption-anchor.value)*100,label=key==='growth'?'Your first year':'Your mature margin';return `${label} is ${number(Math.abs(difference))} percentage points ${difference>=0?'above':'below'} ${anchor.period||anchor.periodEnd}. ${anchor===e.ttm?'TTM comparison; annual history is separate.':'Fiscal-year comparison.'}`;
}
export function renderApprovedEvidence(e,{key='growth',assumption}={}){
 const series=e.series||[],latest=series.at(-1),recent=series.slice(-5).reverse(),low=Math.min(0,...recent.map(r=>r.value||0)),high=Math.max(.01,...recent.map(r=>r.value||0)),span=high-low,zero=-low/span*100,format=v=>e.unit==='percent'?percent(v):finite(v)?number(v,2)+(e.unit==='multiple'?'×':''):'Unavailable';
 const title=key==='growth'?'Revenue growth':key==='targetMargin'?'Operating margin':e.title||'Reported context';
 const stat=(label,value)=>`<div><small>${esc(label)}</small><strong>${esc(format(value))}</strong></div>`;
 const source=latest?.sourceUrl||e.sources?.map(s=>typeof s==='string'?s:s.url||s.sourceUrl||s.sourceURL).find(url);
 const notes=[...new Set(recent.filter(r=>r.comparabilityNote||r.rangeEligible===false).map(r=>r.comparabilityNote||'Excluded from the descriptive range.'))];
 const rowNote=r=>(r.comparabilityNote||r.rangeEligible===false)?notes.indexOf(r.comparabilityNote||'Excluded from the descriptive range.')+1:0;
 return `<div class="approved-history-heading"><div><span class="eyebrow">${e.kind==='proxy'?'REPORTED PROXY':'REPORTED HISTORY'}</span><h2>${esc(title)}</h2></div><span class="approved-readonly">Read only</span></div>${series.length?`<div class="approved-history-stats">${key==='targetMargin'&&e.ttm?stat(e.ttm.period,e.ttm.value)+stat('Latest annual · '+(latest?.period||latest?.periodEnd||''),latest?.value):stat('Latest annual · '+(latest?.period||latest?.periodEnd||''),latest?.value)+(e.range?stat(`${e.range.count}-year median`,e.range.median):'')}</div><div class="approved-history-list" role="table" aria-label="${esc(title)} recent annual observations"><div class="approved-history-labels" role="row"><span role="columnheader">Fiscal year</span><span role="columnheader">${esc(title)}</span><span role="columnheader">${esc(e.unit==='percent'?'%':e.unit||'Value')}</span></div>${recent.map((r,i)=>`<div class="approved-history-row${!finite(r.value)?' is-unavailable':''}" role="row"><span role="rowheader" title="Ended ${esc(r.periodEnd)}">${esc(r.period||r.periodEnd)}${rowNote(r)?`<sup aria-label="Comparability note ${rowNote(r)}">${rowNote(r)}</sup>`:''}</span><span class="approved-history-track" aria-hidden="true" style="--history-zero:${zero}%"><i class="${i===0?'is-latest':''}" style="width:${finite(r.value)?Math.abs(r.value)/span*100:0}%;left:${finite(r.value)&&r.value<0?zero-Math.abs(r.value)/span*100:zero}%"></i></span><span role="cell">${url(r.sourceUrl)?`<a href="${esc(r.sourceUrl)}" target="_blank" rel="noopener" aria-label="${esc(r.period||r.periodEnd)}: ${esc(format(r.value))}; original source">${esc(format(r.value))}</a>`:esc(format(r.value))}</span></div>`).join('')}</div>`:`<p class="approved-empty-history">${esc(e.summary||'No comparable sourced observations are available.')}</p>`}${notes.length?`<ol class="approved-comparability-notes">${notes.map(n=>`<li>${esc(n)}</li>`).join('')}</ol>`:''}<p class="approved-comparison" data-approved-comparison>${esc(evidenceComparison(e,assumption,key))}</p><div class="approved-history-actions"><button type="button" class="text-button" data-approved-history="${esc(key)}">${series.length?'All '+series.length+' annual observations':'Sources & comparability'} ↗</button>${url(source)?`<a href="${esc(source)}" target="_blank" rel="noopener">Original filing ↗</a>`:''}</div><p class="approved-history-basis">${esc(e.summary||'')}</p><p class="approved-history-basis">${esc(e.range?.label||'')} ${esc(e.historyBasis||'Sourced annual observations.')} ${esc(e.coverage?.shortfallReason||'')} ${esc(e.coverage?.comparabilityNote||'')}</p>`;
}
